komponenten-inputs-forms-textfeld--inter.snippet:
import { Component } from '@angular/core';
import { TextFieldComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [TextFieldComponent],
  template: `
    <cds-text-field
        [label]="'E-Mail'"
        [type]="'email'"
        [placeholder]="'name@firma.de'"
        [helper]="'Wir nutzen die Adresse ausschließlich für die Antwort.'"
        [error]="''"
        [required]="true"
        [fieldId]="'demo-email'"
        (disabledChange)="disabledChange($event)"
        (valueChange)="valueChange($event)"
    />`,
})
export class DemoComponent {
  disabledChange(event: unknown) {}
  valueChange(event: unknown) {}
}

